#!/usr/bin/env bash
# Adds "Local Kiosk Users" to the instance detail page — the people who
# operate a specific kiosk terminal day-to-day, distinct from company
# Users (who log into this Admin Panel dashboard).
#
# There's no real Kiosk Application yet with its own on-device login
# screen to enforce this against — this is the admin-side registry a real
# one would eventually read from, managed here in the meantime so it can
# be set up remotely without touching the physical machine. Same design
# philosophy as Items & Tools (also an admin-side, per-instance registry).
#
# PIN handling mirrors the web dashboard's own PIN system: hashed
# (argon2), history-tracked so a PIN can't be reused, and expiry-aware
# using the same Company.pin_expiry_days policy — just scoped per local
# user instead of per dashboard account, and not gating any live login
# anywhere (there's nothing to gate yet).
#
# Tested end-to-end before this was shipped: add with/without a PIN, edit,
# reuse rejection (both the current PIN and a past one from history),
# expiry display, and removal — all verified directly against the
# database, not just HTTP status codes.
#
# Includes a database migration (instance_local_users +
# instance_local_user_pin_history).
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app migrations requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/instances"
cp app/models.py "backups/$TS/models.py.bak" 2>/dev/null || true
cp app/blueprints/instances.py "backups/$TS/instances.py.bak" 2>/dev/null || true
cp app/templates/instances/detail.html "backups/$TS/templates/instances/detail.html.bak" 2>/dev/null || true
cp -r admin_panel.db "backups/$TS/admin_panel.db.bak" 2>/dev/null || true
echo "==> Backed up existing files (incl. a DB copy - this push includes a migration) to backups/$TS/"

echo "==> Writing app/models.py"
base64 -d > app/models.py << 'MODELS_PY_B64'

MODELS_PY_B64

echo "==> Writing app/blueprints/instances.py"
base64 -d > app/blueprints/instances.py << 'INSTANCES_PY_B64'

INSTANCES_PY_B64

echo "==> Writing app/templates/instances/detail.html"
base64 -d > app/templates/instances/detail.html << 'DETAIL_HTML_B64'

DETAIL_HTML_B64

echo "==> Writing new Alembic migration (instance_local_users)"
base64 -d > migrations/versions/b4d8f2a1c6e9_add_instance_local_users.py << 'MIGRATION_PY_B64'

MIGRATION_PY_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/models.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/instances.py').read())"
python3 -c "import ast; ast.parse(open('migrations/versions/b4d8f2a1c6e9_add_instance_local_users.py').read())"
echo "    all Python files: syntax OK"

echo ""
echo "==> Applying database migration (instance_local_users tables)"
source venv/bin/activate
FLASK_APP=run.py python -m flask db upgrade

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Local Kiosk Users live. On any instance's page, below Items & Tools:"
echo "  - Add/edit/remove local kiosk operators (owner/administrator/"
echo "    manager) with an optional PIN."
echo "  - PIN can't be reused (checked against history), and shows"
echo "    Expired once it's past the company's PIN expiry policy."
echo "  - This is admin-side data only - no real kiosk-terminal app exists"
echo "    yet to actually enforce a login against it."
echo "==================================================================="
